// Aim the projector by rotating the rig. Its optical axis is local -Z.
// @param throwRatio = 1.2 (0.1..8)
// @label throwRatio = "Throw ratio"
// @param aspect = 0 (0..8)
// @label aspect = "Aspect ratio (0 = auto)"
// @param intensity = 4 (0..500)
// @label intensity = "Intensity"
// @param range = 20 (0.1..200)
// @label range = "Range"
// @param decay = 0 (0..2)
// @label decay = "Distance falloff"
// @param shadows = true
// @label shadows = "Cast shadows"
// @param grid = false
// @label grid = "Calibration grid"
// @param playing = true
// @label playing = "Play video"

function projectorOptics( throwRatio, aspect ) {

	const width = 0.5 / Math.max( 0.1, throwRatio );
	const height = width / Math.max( 0.1, aspect );
	// Fit the entire picture inside the spotlight cone. The unused area is black.
	return { width, height, radius: Math.hypot( width, height ) * 1.02 };

}
function applyProjectionMask( ctx, mask, x, y, width, height ) {

	if ( ! mask || mask.points?.length < 3 ) return;
	ctx.save();
	ctx.beginPath();
	if ( mask.mode === 'inside' ) ctx.rect( x, y, width, height );
	mask.points.forEach( ( [ u, v ], i ) => {

		const px = x + u * width, py = y + v * height;
		if ( i === 0 ) ctx.moveTo( px, py );
		else ctx.lineTo( px, py );

	} );
	ctx.closePath();
	ctx.fillStyle = '#000';
	ctx.fill( 'evenodd' );
	ctx.restore();

}
function drawTargetAperture( THREE, ctx, scratch, root, target, frame, x, y, width, height ) {

	root.updateWorldMatrix( true, false );
	target?.updateWorldMatrix( true, true );
	const meshes = [];
	const signature = [ target?.uuid, ...root.matrixWorld.elements, frame.aspect, frame.height, frame.range, x, y, width, height ];
	target?.traverseVisible( object => {

		if ( ! object.isMesh || object.isInstancedMesh || object.userData.runtimeOnly || ! object.geometry.attributes.position ) return;
		for ( let parent = object; parent; parent = parent.parent ) if ( parent.userData.threeditor?.disabled || ! parent.visible ) return;
		meshes.push( object );
		const geometry = object.geometry;
		const position = geometry.attributes.position;
		signature.push( geometry.uuid, position.version ?? position.data?.version, geometry.index?.version, ...object.matrixWorld.elements,
			...( object.morphTargetInfluences || [] ) );

	} );
	const key = signature.join( ',' );
	if ( scratch.apertureKey !== key || meshes.some( mesh => mesh.isSkinnedMesh ) ) {

		rasterize( scratch.getContext( '2d' ) );
		scratch.apertureKey = key;

	}
	ctx.save();
	ctx.globalCompositeOperation = 'destination-in';
	ctx.drawImage( scratch, 0, 0 );
	ctx.globalCompositeOperation = 'destination-over';
	ctx.fillStyle = '#000';
	ctx.fillRect( 0, 0, scratch.width, scratch.height );
	ctx.restore();

	function rasterize( ctx ) {
		ctx.clearRect( 0, 0, scratch.width, scratch.height );
		const camera = new THREE.PerspectiveCamera( THREE.MathUtils.radToDeg( 2 * Math.atan( frame.height ) ), frame.aspect, .01, frame.range );
		root.matrixWorld.decompose( camera.position, camera.quaternion, new THREE.Vector3() );
		camera.updateMatrixWorld( true );
		const matrix = new THREE.Matrix4(), vertex = new THREE.Vector4();
		function clip( polygon, distance ) {

			const output = [];
			for ( let i = 0; i < polygon.length; i ++ ) {

				const a = polygon[ i ], b = polygon[ ( i + 1 ) % polygon.length ];
				const da = distance( a ), db = distance( b );
				if ( da >= 0 ) output.push( a );
				if ( ( da >= 0 ) !== ( db >= 0 ) ) output.push( a.clone().lerp( b, da / ( da - db ) ) );

			}
			return output;

		}

		ctx.save();
		ctx.beginPath();
		ctx.rect( x, y, width, height );
		ctx.clip();
		ctx.beginPath();
		for ( const object of meshes ) {

			const geometry = object.geometry;
			const positions = geometry.attributes.position;
			const indices = geometry.index;
			matrix.copy( camera.projectionMatrix ).multiply( camera.matrixWorldInverse ).multiply( object.matrixWorld );
			for ( let i = 0, count = indices?.count ?? positions.count; i + 2 < count; i += 3 ) {

				let polygon = [ 0, 1, 2 ].map( offset => {

					const index = indices ? indices.getX( i + offset ) : i + offset;
					const point = object.getVertexPosition( index, new THREE.Vector3() );
					return vertex.set( point.x, point.y, point.z, 1 ).applyMatrix4( matrix ).clone();

				} );
				polygon = clip( clip( polygon, p => p.w + p.z ), p => p.w - p.z );
				if ( polygon.length < 3 ) continue;
				const points = polygon.map( p => [ x + ( 1 + p.x / p.w ) * width / 2, y + ( 1 - p.y / p.w ) * height / 2 ] );
				const area = points.reduce( ( sum, p, j ) => {

					const q = points[ ( j + 1 ) % points.length ];
					return sum + p[ 0 ] * q[ 1 ] - p[ 1 ] * q[ 0 ];

				}, 0 );
				if ( ! Number.isFinite( area ) || Math.abs( area ) < 1e-8 ) continue;
				if ( area < 0 ) points.reverse();
				ctx.moveTo( ...points[ 0 ] );
				for ( const point of points.slice( 1 ) ) ctx.lineTo( ...point );
				ctx.closePath();

			}

		}
		ctx.fillStyle = '#fff';
		ctx.fill( 'nonzero' );
		ctx.restore();

	}

}
function warpProjection( ctx, scratch, warp, x, y, width, height ) {

	const { size, points } = warp;
	if ( size < 2 || points.length !== size * size ) return;
	const source = scratch.getContext( '2d' );
	source.clearRect( 0, 0, scratch.width, scratch.height );
	source.drawImage( ctx.canvas, 0, 0 );
	const step = 1 / ( size - 1 );
	ctx.save();
	ctx.beginPath();
	ctx.rect( x, y, width, height );
	ctx.clip();
	ctx.fillStyle = '#000';
	ctx.fillRect( x, y, width, height );
	function triangle( indices ) {

		const output = indices.map( i => [ x + i % size * step * width, y + Math.floor( i / size ) * step * height ] );
		const input = indices.map( i => [ x + points[ i ][ 0 ] * width, y + points[ i ][ 1 ] * height ] );
		const [ [ x0, y0 ], [ x1, y1 ], [ x2, y2 ] ] = input;
		const det = ( x1 - x0 ) * ( y2 - y0 ) - ( y1 - y0 ) * ( x2 - x0 );
		if ( Math.abs( det ) < 1e-8 ) return;
		const coefficients = axis => {

			const [ a, b, c ] = output.map( vertex => vertex[ axis ] );
			const m = ( ( b - a ) * ( y2 - y0 ) - ( c - a ) * ( y1 - y0 ) ) / det;
			const n = ( ( c - a ) * ( x1 - x0 ) - ( b - a ) * ( x2 - x0 ) ) / det;
			return [ m, n, a - m * x0 - n * y0 ];

		};
		const [ a, c, e ] = coefficients( 0 ), [ b, d, f ] = coefficients( 1 );
		const center = [ 0, 1 ].map( axis => output.reduce( ( sum, vertex ) => sum + vertex[ axis ], 0 ) / 3 );
		ctx.save();
		ctx.beginPath();
		output.forEach( ( [ u, v ], index ) => {

			const angle = Math.atan2( v - center[ 1 ], u - center[ 0 ] );
			ctx[ index ? 'lineTo' : 'moveTo' ]( u + .75 * Math.cos( angle ), v + .75 * Math.sin( angle ) );

		} );
		ctx.closePath();
		ctx.clip();
		ctx.transform( a, b, c, d, e, f );
		ctx.drawImage( scratch, 0, 0 );
		ctx.restore();

	}
	for ( let row = 0; row < size - 1; row ++ ) for ( let column = 0; column < size - 1; column ++ ) {

		const a = row * size + column, b = a + 1, c = a + size, d = c + 1;
		triangle( [ a, b, d ] );
		triangle( [ a, d, c ] );

	}
	ctx.restore();

}
function projectorRuntime( THREE, root, player ) {

	const canvas = document.createElement( 'canvas' );
	canvas.width = canvas.height = 1024;
	const ctx = canvas.getContext( '2d' );
	const texture = new THREE.CanvasTexture( canvas );
	texture.colorSpace = THREE.SRGBColorSpace;
	const light = new THREE.SpotLight();
	light.position.set( 0, 0, 0 );
	light.map = texture;
	light.penumbra = 0.005;
	light.shadow.bias = - 0.0002;
	light.shadow.mapSize.set( 1024, 1024 );
	light.shadow.camera.near = 0.01;
	light.userData.runtimeOnly = true;
	light.target.position.z = - 1;
	light.add( light.target );
	root.add( light );
	const updateMatrices = light.shadow.updateMatrices.bind( light.shadow );
	light.shadow.updateMatrices = function ( source ) {

		// Follow the rig's roll as well as its forward direction.
		this.camera.up.setFromMatrixColumn( source.matrixWorld, 1 ).normalize();
		updateMatrices( source );

	};

	let settings, media;
	let warpScratch, apertureScratch;
	function mappingCanvas() {

		const scratch = document.createElement( 'canvas' );
		scratch.width = canvas.width;
		scratch.height = canvas.height;
		return scratch;

	}
	let lastTime = - 1;

	function draw() {

		const video = media?.tagName === 'VIDEO';
		const canvasSource = media?.tagName === 'CANVAS';
		const mediaWidth = video ? media.videoWidth : canvasSource ? media.width : media?.naturalWidth;
		const mediaHeight = video ? media.videoHeight : canvasSource ? media.height : media?.naturalHeight;
		const sourceAspect = mediaWidth && mediaHeight ? mediaWidth / mediaHeight : 16 / 9;
		const aspect = settings.aspect || sourceAspect;
		if ( root.projectorFrame?.aspect !== aspect || root.projectorFrame.throwRatio !== settings.throwRatio || root.projectorFrame.range !== light.distance ) {

			root.projectorFrame = { ...projectorOptics( settings.throwRatio, aspect ), aspect, throwRatio: settings.throwRatio, range: light.distance };
			light.angle = Math.atan( root.projectorFrame.radius );

		}
		const frame = root.projectorFrame;

		const w = canvas.width * frame.width / frame.radius, h = canvas.height * frame.height / frame.radius;
		const x = ( canvas.width - w ) / 2, y = ( canvas.height - h ) / 2;
		ctx.fillStyle = '#000';
		ctx.fillRect( 0, 0, canvas.width, canvas.height );

		if ( ! settings.grid && mediaWidth && ( ! video || media.readyState >= 2 ) ) {

			const scale = Math.min( w / mediaWidth, h / mediaHeight );
			const dw = mediaWidth * scale, dh = mediaHeight * scale;
			ctx.drawImage( media, ( canvas.width - dw ) / 2, ( canvas.height - dh ) / 2, dw, dh );

		} else if ( settings.grid || ! media ) {

			ctx.strokeStyle = '#ffffff';
			ctx.lineWidth = Math.min( w, h ) / 160;
			ctx.beginPath();
			ctx.rect( x, y, w, h );
			for ( let i = 1; i < 8; i ++ ) {
				ctx.moveTo( x + i * w / 8, y );
				ctx.lineTo( x + i * w / 8, y + h );
				ctx.moveTo( x, y + i * h / 8 );
				ctx.lineTo( x + w, y + i * h / 8 );
			}
			ctx.stroke();
			ctx.fillStyle = '#ff4040';
			ctx.fillRect( x, y, w / 8, h / 8 );
			ctx.fillStyle = '#40ff80';
			ctx.fillRect( x + 7 * w / 8, y, w / 8, h / 8 );

		}
		if ( root.userData.projectorWarp ) warpProjection( ctx, warpScratch ||= mappingCanvas(), root.userData.projectorWarp, x, y, w, h );
		if ( root.userData.projectorTarget ) {

			let scene = root;
			while ( scene.parent ) scene = scene.parent;
			drawTargetAperture( THREE, ctx, apertureScratch ||= mappingCanvas(), root, scene.getObjectByProperty( 'uuid', root.userData.projectorTarget ), frame, x, y, w, h );

		}
		applyProjectionMask( ctx, root.userData.projectionMask, x, y, w, h );
		root.projectorOutput = { canvas, warpSource: root.userData.projectorWarp && warpScratch, x, y, width: w, height: h, tracking: media?.dataset.tracking,
			trackingHeads: Number( media?.dataset.trackingHeads || 0 ), trackingHands: Number( media?.dataset.trackingHands || 0 ) };
		texture.needsUpdate = true;

	}

	function configure( next ) {

		const wasPlaying = settings?.playing;
		settings = next;
		light.intensity = Math.max( 0, next.intensity );
		light.distance = Math.max( 0.1, next.range );
		light.decay = next.decay;
		light.castShadow = next.shadows;
		if ( media?.tagName === 'VIDEO' && next.playing !== wasPlaying ) {

			if ( next.playing ) media.play().catch( () => {} );
			else media.pause();

		}
		draw();

	}

	function attach( value ) {

		media = value;
		const ready = () => { draw(); player.requestRender?.(); };
		media.onload = ready;
		media.onloadeddata = ready;
		media.onerror = () => player.reportAssetError?.( 'Projector media could not be loaded.' );

	}

	return {
		attach,
		configure,
		update() {

			if ( root.userData.projectorTarget || ! settings.grid && media?.tagName === 'CANVAS' ) {
				draw();
			} else if ( ! settings.grid && media?.readyState >= 2 && media.currentTime !== lastTime ) {
				lastTime = media.currentTime;
				draw();
			}

		},
		dispose() {

			if ( media ) {
				media.onload = media.onloadeddata = media.onerror = null;
				media.pause?.();
				media.removeAttribute( 'src' );
				media.load?.();
			}
			light.removeFromParent();
			texture.dispose();
			light.dispose();
			delete root.projectorFrame;
			delete root.projectorOutput;

		}
	};

}
let projector;
function init() {
 projector = projectorRuntime( THREE, this, player );
 const media = document.createElement( 'video' );
 media.muted = true;
 media.playsInline = true;
 media.loop = true;
 media.preload = 'auto';
 projector.attach( media );
 media.src = "assets/danse-serpentine-lumiere-1897.webm";
 projector.configure( params );
}
function setParameters( next ) {

 projector.configure( next );
 player.requestRender?.();
}
function update() { projector.update(); }
function stop() { projector?.dispose();  }

